{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Pirfenidone, a 5-methyl-1-phenylpyridinone structurally very close to the query's phenyl-methyl azole/one core, is rapidly absorbed with high oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Urapidil shows absolute oral bioavailability of 78% in healthy volunteers, demonstrating that small heteroaromatic drugs in this class readily achieve F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Ondansetron has approximately 60% absolute oral bioavailability in humans, supporting high F for a similarly sized heteroaromatic compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alprazolam has 92% absolute oral bioavailability in humans, supporting high F for a small lipophilic heteroaromatic compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Trazodone shows absolute oral bioavailability of 91% in fasted men, further supporting high F for this class of small heteroaromatic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Acamprosate has only about 11% oral bioavailability under fasting conditions, but this low value is driven by its highly polar, ionized structure and poor permeability, which does not transfer to the lipophilic neutral query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is antipyrine, a small neutral lipophilic pyrazolone. Multiple high-transfer analogues with closely related heteroaromatic scaffolds show absolute oral bioavailability of 60–100% in humans, and the physicochemical prior is favorable. The only low-bioavailability analogue (acamprosate) is a highly polar ionized molecule whose poor permeability does not transfer. Therefore F ≥20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself.",
    "First-pass metabolism and clearance of the query are not directly measured.",
    "The acamprosate low-F evidence is mechanistically non-transferable due to extreme polarity and ionization."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

